
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_bayesian_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_bayesian", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.284723476240098e+00, -4.202918712348919e+00, -4.088420134734726e+00, -3.930083851417541e+00, -3.714906386763339e+00, -3.429739614524098e+00, -3.065260236424907e+00, -2.622978261718303e+00, -2.123797301297413e+00, -1.607003778700137e+00, -1.093022448252137e+00, -7.068473490346235e-01, -6.002593222492209e-01, -4.984963740747938e-01, -3.688848690556649e-01, -2.464002849138452e-01, -1.479924064041595e-01, -6.777494941577408e-02, -1.748310557907878e-02, -2.068815538130576e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


